SELECT bs.state AS state, bs."in.nhgis_tract_gisjoin" AS nhgis_tract_gisjoin, sum(1) AS metadata_rows_count, count(distinct(bs.bldg_id)) AS model_count, sum(bs.weight) AS units_count, sum(bs."out.electricity.total.energy_consumption..kwh" * bs.weight) AS "electricity.total.energy_consumption..kwh" FROM comstock_amy2018_r2_2025_md_by_state_and_county_parquet AS bs WHERE bs.applicability = true AND bs.upgrade = 0 AND bs.state IN ('CO', 'NM') AND bs.bldg_id IN (7225, 7226, 7227, 7228, 7229, 7230, 7231, 7232, 46369, 46370, 46371, 46372, 46373, 46374, 46375, 46376) GROUP BY 1, 2 ORDER BY 1, 2